import { CantOpenDevice } from "@ledgerhq/errors";

let listenObserver: any = null;
const fakeTransport = {
  exchange: jest.fn((buf: Buffer) => Promise.resolve(Buffer.from("aa" + buf.toString("hex"), "hex"))),
  close: jest.fn(() => Promise.resolve()),
};
let openImpl: (id: string) => Promise<any> = () => Promise.resolve(fakeTransport);

jest.mock("@ledgerhq/live-common/hw/index", () => ({
  open: (id: string) => openImpl(id),
}));
jest.mock("@ledgerhq/hw-transport-node-hid-singleton", () => ({
  __esModule: true,
  default: {
    listen: (observer: any) => {
      listenObserver = observer;
      return { unsubscribe: jest.fn() };
    },
  },
}));

import {
  transportOpen,
  transportExchange,
  transportExchangeBulk,
  transportListen,
  transportListenUnsubscribe,
  transportClose,
} from "./transportHandler";

const collect = (obs: any): Promise<any[]> =>
  new Promise((resolve, reject) => {
    const out: any[] = [];
    obs.subscribe({ next: (v: any) => out.push(v), error: reject, complete: () => resolve(out) });
  });

describe("transportHandler", () => {
  beforeEach(() => {
    openImpl = () => Promise.resolve(fakeTransport);
    fakeTransport.exchange.mockClear();
    fakeTransport.close.mockClear();
  });

  it("open success then exchange + bulk + close", async () => {
    const opened = await collect(transportOpen({ data: { descriptor: "d1" }, requestId: "1" } as any));
    expect(opened[0].data).toBeDefined();

    const ex = await collect(
      transportExchange({ data: { descriptor: "d1", apduHex: "01" }, requestId: "2" } as any),
    );
    expect(ex[0].data).toBe("aa01");

    const bulk = await collect(
      transportExchangeBulk({
        data: { descriptor: "d1", apdusHex: ["02", "03"] },
        requestId: "3",
      } as any),
    );
    expect(bulk.map(b => b.data)).toEqual(["aa02", "aa03"]);

    const closed = await collect(
      transportClose({ data: { descriptor: "d1" }, requestId: "4" } as any),
    );
    expect(closed[0]).toEqual({ type: "ok", data: { descriptor: "d1" } });
    expect(fakeTransport.close).toHaveBeenCalled();

    // after close, exchange should error
    const ex2 = await collect(
      transportExchange({ data: { descriptor: "d1", apduHex: "01" }, requestId: "5" } as any),
    );
    expect(ex2[0].error.name).toBe("DisconnectedDeviceDuringOperation");
  });

  it("open failure emits CantOpenDevice", async () => {
    openImpl = () => Promise.reject(new CantOpenDevice("nope"));
    const opened = await collect(transportOpen({ data: { descriptor: "z" }, requestId: "1" } as any));
    expect(opened[0].error.name).toBe("CantOpenDevice");
  });

  it("exchange without open errors", async () => {
    const ex = await collect(
      transportExchange({ data: { descriptor: "nope", apduHex: "01" }, requestId: "2" } as any),
    );
    expect(ex[0].error.name).toBe("DisconnectedDeviceDuringOperation");
  });

  it("listen emits events and unsubscribe completes", async () => {
    const events: any[] = [];
    let completed = false;
    transportListen({ requestId: "L1" } as any).subscribe({
      next: v => events.push(v),
      complete: () => {
        completed = true;
      },
    });
    listenObserver.next({ type: "add", descriptor: "path1" });
    listenObserver.next({ type: "remove", descriptor: "path1" });
    expect(events).toEqual([
      { data: { type: "add", descriptor: "path1" } },
      { data: { type: "remove", descriptor: "path1" } },
    ]);

    const unsub = await collect(transportListenUnsubscribe({ requestId: "L1" } as any));
    expect(unsub).toEqual([]);
    expect(completed).toBe(true);
  });
});
