ACpD,CAAC;KACF,CAAC,CAAC;IAEH,eAAe,CAAC,GAAG,CAAC,SAAS,EAAE,EAAE,QAAQ,EAAE,GAAG,EAAE,CAAC,UAAU,CAAC,QAAQ,EAAE,EAAE,CAAC,CAAC;IAE1E,OAAO,GAAG,EAAE;QACV,YAAY,CAAC,WAAW,EAAE,CAAC;QAC3B,eAAe,CAAC,MAAM,CAAC,SAAS,CAAC,CAAC;IACpC,CAAC,CAAC;AACJ,CAAC,CAAC,CAAC;AAtBQ,QAAA,eAAe,mBAsBvB;AAEL;;;;;GAKG;AACI,MAAM,0BAA0B,GAAG,CAAC,EACzC,SAAS,GACmC,EAAqB,EAAE,CACnE,IAAI,iBAAU,CAAC,UAAU,CAAC,EAAE;IAC1B,MAAM,QAAQ,GAAG,eAAe,CAAC,GAAG,CAAC,SAAS,CAAC,CAAC;IAChD,IAAI,QAAQ,EAAE;QACZ,QAAQ,CAAC,QAAQ,EAAE,CAAC;QACpB,eAAe,CAAC,MAAM,CAAC,SAAS,CAAC,CAAC;KACnC;IACD,UAAU,CAAC,QAAQ,EAAE,CAAC;AACxB,CAAC,CAAC,CAAC;AAVQ,QAAA,0BAA0B,8BAUlC;AAEL;;;;;;GAMG;AACI,MAAM,cAAc,GAAG,CAAC,EAC7B,IAAI,GAC2B,EAAyD,EAAE,CAC1F,IAAI,iBAAU,CAAC,UAAU,CAAC,EAAE;IAC1B,MAAM,SAAS,GAAG,UAAU,CAAC,GAAG,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC;IAClD,IAAI,CAAC,SAAS,EAAE;QACd,UAAU,CAAC,IAAI,CAAC;YACd,KAAK,EAAE,IAAA,uBAAc,EACnB,IAAI,0CAAiC,CAAC,4CAA4C,CAAC,CACpF;SACF,CAAC,CAAC;QACH,UAAU,CAAC,QAAQ,EAAE,CAAC;QACtB,OAAO;KACR;IAED,OAAO,CAAC,OAAO,CAAC,SAAS,CAAC,KAAK,EAAE,CAAC;SAC/B,IAAI,CAAC,GAAG,EAAE;QACT,UAAU,CAAC,MAAM,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC;QACnC,UAAU,CAAC,IAAI,CAAC,EAAE,IAAI,EAAE,IAAI,EAAE,IAAI,EAAE,CAAC,CAAC;QACtC,UAAU,CAAC,QAAQ,EAAE,CAAC;IACxB,CAAC,CAAC;SACD,KAAK,CAAC,KAAK,CAAC,EAAE;QACb,UAAU,CAAC,MAAM,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC;QACnC,UAAU,CAAC,IAAI,CAAC,EAAE,KAAK,EAAE,IAAA,uBAAc,EAAC,KAAK,CAAC,EAAE,CAAC,CAAC;QAClD,UAAU,CAAC,QAAQ,EAAE,CAAC;IACxB,CAAC,CAAC,CAAC;AACP,CAAC,CAAC,CAAC;AA1BQ,QAAA,cAAc,kBA0BtB","names":[],"sources":["/workspace/repo/apps/ledger-live-desktop/src/internal/transportHandler.ts"],"sourcesContent":["import { Observable } from \"rxjs\";\nimport Transport from \"@ledgerhq/hw-transport\";\nimport TransportNodeHidSingleton from \"@ledgerhq/hw-transport-node-hid-singleton\";\nimport { open } from \"@ledgerhq/live-common/hw/index\";\nimport { DisconnectedDeviceDuringOperation, serializeError } from \"@ledgerhq/errors\";\nimport { MessagesMap } from \"./types\";\n\n// A serialized error, as produced by `serializeError`, holding at least a `name`\n// and a `message` so that it can be re-hydrated on the consumer side.\ntype SerializedError = ReturnType<typeof serializeError>;\n\n// Every transport operation returns an Observable emitting these structured\n// responses. A response either carries some `data`, an `error`, or (for the\n// close operation) an explicit `{ type: \"ok\" }` acknowledgement.\nexport type TransportResponse<Data = unknown> =\n  | { data: Data }\n  | { error: SerializedError }\n  | { type: \"ok\"; data: Data };\n\n// Store of the transports that are currently open, keyed by their descriptor.\nconst transports = new Map<string, Transport>();\n\n// Keeps a reference to the observers of the ongoing `transportListen` streams so\n// that `transportListenUnsubscribe` can complete them by request id.\nconst listenObservers = new Map<string, { complete: () => void }>();\n\n// Keeps a reference to the observers of the ongoing `transportExchangeBulk`\n// streams so that they can be cancelled by request id.\nconst bulkObservers = new Map<string, { complete: () => void }>();\n\n/**\n * Opens a transport for the given descriptor.\n *\n * Emits `{ data }` once a transport is available (or was already open), and\n * `{ error }` (with a `CantOpenDevice` error) when no registered transport\n * module can handle the descriptor.\n */\nexport const transportOpen = ({\n  data,\n}: MessagesMap[\"transport:open\"]): Observable<TransportResponse<{ descriptor: string }>> =>\n  new Observable(subscriber => {\n    // If a transport is already open for this descriptor, simply acknowledge it.\n    if (transports.has(data.descriptor)) {\n      subscriber.next({ data });\n      subscriber.complete();\n      return;\n    }\n\n    open(data.descriptor)\n      .then(transport => {\n        transports.set(data.descriptor, transport);\n        subscriber.next({ data });\n        subscriber.complete();\n      })\n      .catch(error => {\n        subscriber.next({ error: serializeError(error) });\n        subscriber.complete();\n      });\n  });\n\n/**\n * Exchanges a single APDU with the device.\n *\n * Emits `{ data }` with the hex string of the response buffer on success, and\n * `{ error }` (a `DisconnectedDeviceDuringOperation`) if no transport is open\n * for the descriptor or the exchange fails.\n */\nexport const transportExchange = ({\n  data,\n}: MessagesMap[\"transport:exchange\"]): Observable<TransportResponse<string>> =>\n  new Observable(subscriber => {\n    const transport = transports.get(data.descriptor);\n    if (!transport) {\n      subscriber.next({\n        error: serializeError(\n          new DisconnectedDeviceDuringOperation(\"No open transport for the given descriptor\"),\n        ),\n      });\n      subscriber.complete();\n      return;\n    }\n\n    transport\n      .exchange(Buffer.from(data.apduHex, \"hex\"))\n      .then(response => {\n        subscriber.next({ data: response.toString(\"hex\") });\n        subscriber.complete();\n      })\n      .catch(error => {\n        subscriber.next({\n          error: serializeError(\n            new DisconnectedDeviceDuringOperation((error as Error)?.message ?? String(error)),\n          ),\n        });\n        subscriber.complete();\n      });\n  });\n\n/**\n * Exchanges an ordered list of APDUs with the device.\n *\n * Emits one response per APDU: `{ data }` with the hex string of the response\n * on success, or `{ error }` (a `DisconnectedDeviceDuringOperation`) on\n * failure. If no transport is open for the descriptor, a single `{ error }` is\n * emitted instead.\n */\nexport const transportExchangeBulk = ({\n  data,\n  requestId,\n}: MessagesMap[\"transport:exchangeBulk\"]): Observable<TransportResponse<string>> =>\n  new Observable(subscriber => {\n    const transport = transports.get(data.descriptor);\n    if (!transport) {\n      subscriber.next({\n        error: serializeError(\n          new DisconnectedDeviceDuringOperation(\"No open transport for the given descriptor\"),\n        ),\n      });\n      subscriber.complete();\n      return;\n    }\n\n    let cancelled = false;\n    bulkObservers.set(requestId, {\n      complete: () => {\n        cancelled = true;\n        subscriber.complete();\n      },\n    });\n\n    (async () => {\n      for (const apduHex of data.apdusHex) {\n        if (cancelled) return;\n        try {\n          const response = await transport.exchange(Buffer.from(apduHex, \"hex\"));\n          if (cancelled) return;\n          subscriber.next({ data: response.toString(\"hex\") });\n        } catch (error) {\n          if (cancelled) return;\n          subscriber.next({\n            error: serializeError(\n              new DisconnectedDeviceDuringOperation((error as Error)?.message ?? String(error)),\n            ),\n          });\n        }\n      }\n      subscriber.complete();\n    })();\n\n    return () => {\n      cancelled = true;\n      bulkObservers.delete(requestId);\n    };\n  });\n\n/**\n * Cancels an ongoing `transportExchangeBulk` stream identified by its request\n * id. Returns an Observable that completes immediately without emitting.\n */\nexport const transportExchangeBulkUnsubscribe = ({\n  requestId,\n}: MessagesMap[\"transport:exchangeBulk:unsubscribe\"]): Observable<never> =>\n  new Observable(subscriber => {\n    const observer = bulkObservers.get(requestId);\n    if (observer) {\n      observer.complete();\n      bulkObservers.delete(requestId);\n    }\n    subscriber.complete();\n  });\n\n/**\n * Listens to device add/remove events.\n *\n * Emits `{ data: { type, descriptor } }` for each event until the stream is\n * unsubscribed (see `transportListenUnsubscribe`).\n */\nexport const transportListen = ({\n  requestId,\n}: MessagesMap[\"transport:listen\"]): Observable<\n  TransportResponse<{ type: \"add\" | \"remove\"; descriptor: string }>\n> =>\n  new Observable(subscriber => {\n    const subscription = new Observable(TransportNodeHidSingleton.listen).subscribe({\n      next: e => {\n        const event = e as { type: \"add\" | \"remove\"; descriptor: string };\n        subscriber.next({ data: { type: event.type, descriptor: event.descriptor } });\n      },\n      error: error => {\n        subscriber.next({ error: serializeError(error) });\n      },\n    });\n\n    listenObservers.set(requestId, { complete: () => subscriber.complete() });\n\n    return () => {\n      subscription.unsubscribe();\n      listenObservers.delete(requestId);\n    };\n  });\n\n/**\n * Stops the `transportListen` stream identified by its request id.\n *\n * Completes the corresponding listen Observable (so it stops emitting events)\n * and returns an Observable that completes immediately without emitting.\n */\nexport const transportListenUnsubscribe = ({\n  requestId,\n}: MessagesMap[\"transport:listen:unsubscribe\"]): Observable<never> =>\n  new Observable(subscriber => {\n    const observer = listenObservers.get(requestId);\n    if (observer) {\n      observer.complete();\n      listenObservers.delete(requestId);\n    }\n    subscriber.complete();\n  });\n\n/**\n * Closes the transport for the given descriptor.\n *\n * Calls the underlying transport's `close()` method, removes it from the\n * internal store and emits `{ type: \"ok\", data }`. If no transport is open for\n * the descriptor, emits `{ error }` (a `DisconnectedDeviceDuringOperation`).\n */\nexport const transportClose = ({\n  data,\n}: MessagesMap[\"transport:close\"]): Observable<TransportResponse<{ descriptor: string }>> =>\n  new Observable(subscriber => {\n    const transport = transports.get(data.descriptor);\n    if (!transport) {\n      subscriber.next({\n        error: serializeError(\n          new DisconnectedDeviceDuringOperation(\"No open transport for the given descriptor\"),\n        ),\n      });\n      subscriber.complete();\n      return;\n    }\n\n    Promise.resolve(transport.close())\n      .then(() => {\n        transports.delete(data.descriptor);\n        subscriber.next({ type: \"ok\", data });\n        subscriber.complete();\n      })\n      .catch(error => {\n        transports.delete(data.descriptor);\n        subscriber.next({ error: serializeError(error) });\n        subscriber.complete();\n      });\n  });\n"],"version":3}
